// Get the backup data from Export node and save result
const backupData = $('Export All Tables').first().json.backup;
const saveResult = $('Save to Backup DB').first().json;

// Calculate stats
const tables = backupData.tables;
const tableNames = Object.keys(tables);
const tableCount = tableNames.length;
let totalRecords = 0;
let tableDetails = [];

for (const name of tableNames) {
  const count = tables[name].count || 0;
  totalRecords += count;
  tableDetails.push(`${name}: ${count}`);
}

const backupSize = Math.round(JSON.stringify(backupData).length / 1024);
const success = saveResult.id ? true : false;
const icon = success ? '✅' : '❌';
const priority = success ? 3 : 5;
const tag = success ? 'white_check_mark' : 'x';

// Build notification
const title = `${icon} TML Backup: ${tableCount} tables | ${totalRecords} records`;
const message = `Backup ID: ${saveResult.id || 'FAILED'}\nSize: ~${backupSize}KB\nTime: ${new Date().toLocaleTimeString('en-US', {hour: 'numeric', minute: '2-digit', hour12: true})}\n\n${tableDetails.join('\n')}`;

return [{
  json: {
    topic: 'tml-backup',
    title: title,
    message: message,
    priority: priority,
    tags: [tag, 'floppy_disk'],
    click: 'https://n8n2.mattmariani.com'
  }
}];
